UPDATE report
SET visibility_status = #{toStatus},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND visibility_status = #{fromStatus}

UPDATE report
SET processing_status = #{toStatus}, updated_at = #{updatedAt}
WHERE id = #{id}
  AND processing_status IN
#{s}

UPDATE report
SET processing_status = 'CONFIRMED',
    examination_date = #{examinationDate},
    confirmed_by = #{confirmedBy},
    confirmed_at = #{confirmedAt},
    version = version + 1,
    updated_at = #{confirmedAt}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND processing_status = 'PENDING_CONFIRMATION'

UPDATE report
SET examination_date = #{examinationDate},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND processing_status = 'CONFIRMED'

UPDATE report
SET title = #{title},
    examination_date = #{examinationDate},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND visibility_status = 'NORMAL'
